\copy (select p.piece_id, p.piece_pm_id, (p.piece_name is not null and trim(p.piece_name)<>'' and p.piece_fil_name is not null and trim(p.piece_fil_name)<>'') as v3_ok, p.piece_has_img, min(pp.pri_dispo) from pieces_price pp join pieces p on p.piece_id = nullif(pp.pri_piece_id,'')::int where pp.pri_dispo in ('1','2','3') and pp.pricing_state is distinct from 'FROZEN' and pp.pri_vente_ttc_n > 0 and p.piece_display = true group by 1,2,3,4) to '<DIR>/data/vendable.csv' csv
